import itertools,json
A=[('MQR',{1}),('PQR',{1,7}),('KNR',{3,6}),('LNP',{3}),('NPR',{1,5,7})]
B=[('KMQ',{6,8}),('KPR',{2,7}),('LPR',{3,7,8}),('KNQ',{1,2,4}),('KPQ',{4})]
def assignments(rows):
    return [x for x in itertools.product(*(r[0] for r in rows)) if len(set(x))==5]
a=assignments(A);b=assignments(B)
counts={}; witnesses={}; total=0
for x in a:
 for y in b:
  common=set(x)&set(y)
  if len(common)!=3 or len(common&set('KLQ'))!=1: continue
  days={p:set() for p in 'KLMNPQR'}
  for ids,rows in [(x,A),(y,B)]:
   for p,(_,d) in zip(ids,rows): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  total+=1;counts[n]=counts.get(n,0)+1
  witnesses.setdefault(n,{'A':''.join(x),'B':''.join(y)})
lo=min(counts);hi=max(counts)
print(json.dumps({'feasible_linkages':total,'bounds':[lo,hi],'low_witness':witnesses[lo],'high_witness':witnesses[hi],'decision':'confirmed' if lo>=5 else 'excluded' if hi<5 else 'undetermined'}))
print('distribution',counts)

