 return [x for x in itertools.product(*(r[0] for r in rows)) if len(set(x))==5]
counts={}; witnesses={}
for a in assignments(A):
 if a[0]!='M': continue
 for b in assignments(B):
  if a[4]!=b[3]: continue
  common=set(a)&set(b)
  if len(common)!=3 or len(common&set('KLQ'))!=1: continue
  days={p:set() for p in 'KLMNPQR'}
  for ids,rows in [(a,A),(b,B)]:
   for p,(_,d) in zip(ids,rows): days[p].update(d)
  n=sum(len(d)>=3 for d in days.values())
  counts[n]=counts.get(n,0)+1
  witnesses.setdefault(n,{'A':''.join(a),'B':''.join(b)})
lo=min(counts);hi=max(counts)
print(json.dumps({'feasible_linkages':sum(counts.values()),'bounds':[lo,hi],'low_witness':witnesses[lo],'high_witness':witnesses[hi],'decision':'confirmed' if lo>=5 else 'excluded' if hi<5 else 'undetermined'}))
print(counts)

